1	import { resolve } from 'node:path';
2	import { z } from 'zod';
3	import { defineTool, runAgent, type Tool } from '@dailies/agent';
4	import { Beat, type Entry, type IngestArtifact, type Session } from '@dailies/core';
5	import { editorPrompt } from '../prompts/editor';
6	import type { Stage } from '../types';
7	import type { StageDeps } from './index';
8	
9	export interface EditArtifact { beats: Beat[] }
10	
11	const MAX_BEATS = 6;
12	const MAX_ENTRIES_PER_READ = 40;
13	const ENTRY_TEXT_CHARS = 600;
14	const FIRST_PROMPT_CHARS = 200;
15	const MAX_MATCHES = 20;
16	const SNIPPET_CHARS = 200;
17	const MIN_SHA_PREFIX = 7;
18	const COMMAND_CHARS = 600;
19	const PATH_CHARS = 300;
20	const NAME_CHARS = 80;
21	const MAX_LISTED_COMMITS = 40;
22	const LABEL_CHARS = 80;
23	
24	/** `text` in at most `max` characters; a cut is marked with an ellipsis that counts towards the limit. */
25	export function cut(text: string, max: number): string {
26	  return text.length <= max ? text : `${text.slice(0, max - 1)}…`;
27	}
28	
29	/** `text` as one line of at most `max` characters: line breaks and control characters become single spaces. */
30	export function oneLine(text: string, max: number): string {
31	  // eslint-disable-next-line no-control-regex
32	  return cut(text.replace(/[\u0000-\u001f\u007f\u0085\u2028\u2029\s]+/g, ' ').trim(), max);
33	}
34	
35	/** Added and removed line counts of one file's patch, headers excluded. */
36	export function patchCounts(patch: string): { added: number; removed: number } {
37	  let added = 0;
38	  let removed = 0;
39	  for (const line of patch.split('\n')) {
40	    if (line.startsWith('+') && !line.startsWith('+++')) added += 1;
41	    else if (line.startsWith('-') && !line.startsWith('---')) removed += 1;
42	  }
43	  return { added, removed };
44	}
45	
46	/**
47	 * `owner/name` for a remote URL, the directory name for a local path. It goes into prompts and onto the title
48	 * card, so it is built from path segments only (a URL's credentials never reach it), kept to one short line,
49	 * and never falls back to the raw input.
50	 */
51	export function repoLabel(repoUrl: string): string {
52	  const scp = /^[^@/\s]+@[^:/\s]+:(.+)$/.exec(repoUrl);   // git@host:owner/name
53	  const url = /^[a-z][a-z0-9+.-]*:\/\//i.test(repoUrl);
54	  const remote = scp !== null || url;
55	  const path = scp ? scp[1]! : url ? urlPath(repoUrl) : resolve(repoUrl);
56	  // eslint-disable-next-line no-control-regex
57	  const segments = path.replace(/[\u0000-\u001f\u007f]+/g, ' ').split('/').map((part) => part.trim()).filter(Boolean);
58	  const label = segments.slice(remote ? -2 : -1).join('/').replace(/\.git$/, '');
59	  return cut(label, LABEL_CHARS) || 'repository';
60	}
61	
62	function urlPath(url: string): string {
63	  try {
64	    const { pathname } = new URL(url);
65	    try {
66	      return decodeURIComponent(pathname);
67	    } catch {
68	      return pathname;
69	    }
70	  } catch {
71	    return '';
72	  }
73	}
74	
75	/** Every commit the artifact knows: the ones linked to a session and the ones it holds a patch for. */
76	export function knownCommits(ingest: IngestArtifact): string[] {
77	  const shas = new Set(ingest.sessions.flatMap((s) => s.commits));
78	  for (const key of Object.keys(ingest.diffs)) shas.add(key.slice(0, key.indexOf(':')));
79	  return [...shas];
80	}
81	
82	/** The full hash `sha` stands for: itself when known, or the one known commit it is a prefix of. */
83	export function resolveCommit(sha: string, known: string[]): string | null {
84	  if (known.includes(sha)) return sha;
85	  if (sha.length < MIN_SHA_PREFIX) return null;
86	  const matches = known.filter((k) => k.startsWith(sha));
87	  return matches.length === 1 ? matches[0]! : null;
88	}
89	
90	const cutOptional = (text: string | undefined, max: number) => (text === undefined ? undefined : cut(text, max));
91	
92	// Ingest bounds an entry's text but not its command, file path or tool name, so every string is cut here.
93	function entryView(e: Entry) {
94	  return {
95	    id: e.id,
96	    index: e.index,
97	    kind: e.kind,
98	    text: cut(e.text, ENTRY_TEXT_CHARS),
99	    toolName: cutOptional(e.toolName, NAME_CHARS),
100	    command: cutOptional(e.command, COMMAND_CHARS),
101	    filePath: cutOptional(e.filePath, PATH_CHARS),
102	    isError: e.isError,
103	  };
104	}
105	
106	/** The editor's read-only view of the ingest artifact. Every result is bounded, whatever the transcript holds. */
107	export function transcriptTools(ingest: IngestArtifact): Tool[] {
108	  const sessions = new Map(ingest.sessions.map((s) => [s.id, s]));
109	  const commits = knownCommits(ingest);
110	  const sessionOf = (id: string): Session => {
111	    const found = sessions.get(id);
112	    if (!found) throw new Error(`unknown session: ${id}`);
113	    return found;
114	  };
115	  const commitOf = (sha: string): string => {
116	    const found = resolveCommit(sha, commits);
117	    if (!found) throw new Error(`unknown commit: ${sha}`);
118	    return found;
119	  };
120	
121	  return [
122	    defineTool({
123	      name: 'list_sessions',
124	      description: 'List every recorded session in the window: id, agent, model, start, end, entry count, linked commits and the first human prompt.',
125	      parameters: z.object({}),
126	      execute: async () =>
127	        ingest.sessions.map((s) => ({
128	          id: s.id,
129	          agent: cut(s.agent, NAME_CHARS),
130	          model: s.model === null ? null : cut(s.model, NAME_CHARS),
131	          start: s.startedAt,
132	          end: s.endedAt,
133	          entryCount: s.entries.length,
134	          commits: s.commits.slice(0, MAX_LISTED_COMMITS),
135	          firstPrompt: cut(s.entries.find((e) => e.kind === 'user')?.text ?? '', FIRST_PROMPT_CHARS),
136	        })),
137	    }),
138	    defineTool({
139	      name: 'read_entries',
140	      description: `Read the entries of a session from index "from" to index "to", both included. Returns at most ${MAX_ENTRIES_PER_READ} entries per call; "next" is the index to continue from, or null.`,
141	      parameters: z.object({ sessionId: z.string(), from: z.number().int(), to: z.number().int() }),
142	      execute: async ({ sessionId, from, to }) => {
143	        const session = sessionOf(sessionId);
144	        const start = Math.max(0, from);
145	        const end = Math.min(to, session.entries.length - 1);
146	        const entries = session.entries.slice(start, end + 1).slice(0, MAX_ENTRIES_PER_READ);
147	        const next = start + entries.length;
148	        return { entries: entries.map(entryView), entryCount: session.entries.length, next: next <= end ? next : null };
149	      },
150	    }),
151	    defineTool({
152	      name: 'search_transcript',
153	      description: `Find entries whose text or command contains the query, ignoring case, across every session. Returns up to ${MAX_MATCHES} matches with their entry ids.`,
154	      parameters: z.object({ query: z.string().min(1) }),
155	      execute: async ({ query }) => {
156	        const needle = query.toLowerCase();
157	        const matches: { id: string; sessionId: string; index: number; kind: Entry['kind']; snippet: string }[] = [];
158	        let more = false;
159	        for (const entry of ingest.sessions.flatMap((s) => s.entries)) {
160	          const haystack = `${entry.command ?? ''}\n${entry.text}`;
161	          const at = haystack.toLowerCase().indexOf(needle);
162	          if (at === -1) continue;
163	          if (matches.length === MAX_MATCHES) {
164	            more = true;
165	            break;
166	          }
167	          const from = Math.max(0, at - SNIPPET_CHARS / 2);
168	          matches.push({ id: entry.id, sessionId: entry.sessionId, index: entry.index, kind: entry.kind, snippet: haystack.slice(from, from + SNIPPET_CHARS).trim() });
169	        }
170	        return { matches, more };
171	      },
172	    }),
173	    defineTool({
174	      name: 'get_diff',
175	      description: 'List the files a commit changed, with added and removed line counts.',
176	      parameters: z.object({ sha: z.string() }),
177	      execute: async ({ sha }) => {
178	        const prefix = `${commitOf(sha)}:`;
179	        const files = Object.entries(ingest.diffs)
180	          .filter(([key]) => key.startsWith(prefix))
181	          .map(([key, patch]) => ({ path: key.slice(prefix.length), ...patchCounts(patch) }));
182	        return { files };
183	      },
184	    }),
185	    defineTool({
186	      name: 'get_patch',
187	      description: 'Read the patch of one file in one commit.',
188	      parameters: z.object({ sha: z.string(), path: z.string() }),
189	      execute: async ({ sha, path }) => {
190	        const patch = ingest.diffs[`${commitOf(sha)}:${path}`];
191	        if (patch === undefined) throw new Error(`no patch for ${path} in ${sha}`);
192	        return { patch };
193	      },
194	    }),
195	  ];
196	}
197	
198	// The id is ours to assign, and a beat with no commits is still a beat.
199	const BeatDraft = Beat.omit({ id: true }).extend({ commits: z.array(z.string()).default([]) });
200	const EditorReply = z.object({ beats: z.array(BeatDraft) });
201	
202	/** Why a beat cannot be used, or null when every session and range it names exists. */
203	function beatProblem(beat: z.infer<typeof BeatDraft>, sessions: Map<string, Session>): string | null {
204	  for (const id of beat.sessionIds) if (!sessions.has(id)) return `unknown session ${id}`;
205	  for (const range of beat.entryRanges) {
206	    const session = sessions.get(range.sessionId);
207	    if (!session) return `unknown session ${range.sessionId}`;
208	    if (range.from < 0 || range.to < range.from || range.to >= session.entries.length) {
209	      return `range ${range.from}..${range.to} is outside session ${range.sessionId} (${session.entries.length} entries)`;
210	    }
211	  }
212	  return null;
213	}
214	
215	export function editStage(deps: StageDeps): Stage<EditArtifact> {
216	  return {
217	    name: 'edit',
218	    maxAttempts: 3,
219	    async run(ctx) {
220	      const ingest = ctx.read<IngestArtifact>('ingest');
221	      const sessions = new Map(ingest.sessions.map((s) => [s.id, s]));
222	      const commits = knownCommits(ingest);
223	
224	      const { system, user } = editorPrompt({
225	        repo: repoLabel(ctx.run.repoUrl),
226	        since: ctx.run.since,
227	        until: ctx.run.until,
228	        sessionCount: ingest.sessions.length,
229	        maxBeats: MAX_BEATS,
230	      });
231	      const { output, steps } = await runAgent({ client: deps.client, role: 'editor', name: 'editor', system, user, tools: transcriptTools(ingest), output: EditorReply });
232	
233	      const usable: z.infer<typeof BeatDraft>[] = [];
234	      for (const draft of output.beats) {
235	        const problem = beatProblem(draft, sessions);
236	        if (problem) ctx.log(`dropped beat "${draft.title}": ${problem}`);
237	        else usable.push(draft);
238	      }
239	      if (usable.length === 0) throw new Error('the editor returned no usable beat');
240	      if (usable.length > MAX_BEATS) ctx.log(`kept the first ${MAX_BEATS} of ${usable.length} beats`);
241	
242	      const beats: Beat[] = usable.slice(0, MAX_BEATS).map((draft, n) => ({
243	        ...draft,
244	        id: `beat_${n + 1}`,
245	        commits: [...new Set(draft.commits.flatMap((sha) => resolveCommit(sha, commits) ?? []))],
246	      }));
247	      ctx.log(`${beats.length} beats in ${steps} editor steps`);
248	      return { artifact: { beats } };
249	    },
250	  };
251	}
