1	import { readFileSync, existsSync } from 'node:fs';
2	import { resolve } from 'node:path';
3	export interface Env {
4	  neatlogsApiKey: string | null; neatlogsEndpoint: string;
5	  gatewayKey: string | null; gatewayBaseUrl: string;
6	  veniceKey: string | null; geminiKeys: string[]; dataDir: string;
7	}
8	export function loadEnv(cwd = process.cwd()): Env {
9	  const file = resolve(cwd, '.env');
10	  if (existsSync(file)) for (const line of readFileSync(file, 'utf8').split('\n')) {
11	    const m = /^([A-Z0-9_]+)=(.*)$/.exec(line.trim());
12	    if (m && process.env[m[1]!] === undefined) process.env[m[1]!] = m[2]!.replace(/^["']|["']$/g, '');
13	  }
14	  const e = process.env;
15	  return {
16	    neatlogsApiKey: e.NEATLOGS_API_KEY || null,
17	    neatlogsEndpoint: e.NEATLOGS_ENDPOINT || 'https://ingest.neatlogs.com',
18	    gatewayKey: e.LITELLM_API_KEY || null,
19	    gatewayBaseUrl: e.LITELLM_BASE_URL || 'https://litellm.vision.aivar.app/v1',
20	    veniceKey: e.VENICE_API_KEY || null,
21	    geminiKeys: (e.GEMINI_API_KEYS || '').split(',').map((s) => s.trim()).filter(Boolean),
22	    dataDir: resolve(cwd, e.DAILIES_DATA_DIR || '.dailies'),
23	  };
24	}
