import { describe, expect, it } from 'vitest';
import { CostMeter } from '@dailies/agent';
import { StageBudgetError, stageMeter } from '../src/budget';

describe('stageMeter', () => {
  it('does not throw while the stage stays within its share', () => {
    const meter = new CostMeter(10);
    const budget = stageMeter(meter, 1);

    budget.check();
    meter.add(1);
    expect(() => budget.check()).not.toThrow();
    expect(budget.spent()).toBeCloseTo(1);
  });

  it('throws StageBudgetError once the stage spends past its share', () => {
    const meter = new CostMeter(10);
    const budget = stageMeter(meter, 1);

    meter.add(1.01);
    expect(() => budget.check()).toThrow(StageBudgetError);
  });

  it('counts only what was spent after the meter was wrapped, not an earlier stage\'s spend', () => {
    const meter = new CostMeter(10);
    meter.add(5); // spent by a stage that ran before this one

    const budget = stageMeter(meter, 1);
    meter.add(0.9);

    expect(() => budget.check()).not.toThrow();
    expect(budget.spent()).toBeCloseTo(0.9);
  });
});

import { describe, expect, it } from 'vitest';
import { fallbackBeats, outlineSession, outlinesWithin } from '../src/outline';
import { FAILED_RUN, PASSED_RUN, SHA_A, SHA_B, session } from './stages/fixture';

describe('outlineSession', () => {
  it('summarises a session: trimmed prompt and last message, runs in order, edit count', () => {
    const s = session(
      's1',
      [
        { kind: 'user', text: 'Please fix the retry bug in the queue worker so it backs off correctly.' },
        { kind: 'assistant', text: 'Looking at the queue now.' },
        { kind: 'tool_call', toolName: 'Edit', toolUseId: 't1', filePath: 'src/queue.ts', text: '{}' },
        { kind: 'tool_result', toolUseId: 't1', text: 'ok' },
        { kind: 'tool_call', toolName: 'Bash', toolUseId: 't2', command: 'pnpm vitest run', text: '{}' },
        { kind: 'tool_result', toolUseId: 't2', text: FAILED_RUN, isError: true },
        { kind: 'tool_call', toolName: 'Edit', toolUseId: 't3', filePath: 'src/queue.ts', text: '{}' },
        { kind: 'tool_result', toolUseId: 't3', text: 'ok' },
        { kind: 'tool_call', toolName: 'Bash', toolUseId: 't4', command: 'pnpm vitest run', text: '{}' },
        { kind: 'tool_result', toolUseId: 't4', text: PASSED_RUN },
        { kind: 'assistant', text: 'The retry now backs off and all tests pass.' },
      ],
      { commits: [SHA_A], filesTouched: ['src/queue.ts'] },
    );

    const outline = outlineSession(s);

    expect(outline.id).toBe('s1');
    expect(outline.agent).toBe('claude-code');
    expect(outline.turns).toBe(1);
    expect(outline.entries).toBe(11);
    expect(outline.firstPrompt).toBe('Please fix the retry bug in the queue worker so it backs off correctly.');
    expect(outline.lastMessage).toBe('The retry now backs off and all tests pass.');
    expect(outline.edits).toBe(2);
    expect(outline.runs).toEqual(['test fail @4', 'test pass @8']);
    expect(outline.commits).toEqual([SHA_A]);
    expect(outline.files).toEqual(['src/queue.ts']);
  });

  it('cuts the first prompt and the last message to 240 characters', () => {
    const s = session('long', [{ kind: 'user', text: 'p'.repeat(500) }, { kind: 'assistant', text: 'a'.repeat(500) }]);

    const outline = outlineSession(s);

    expect(outline.firstPrompt).toHaveLength(240);
    expect(outline.lastMessage).toHaveLength(240);
  });

  it('caps commits, files and runs', () => {
    const manyRuns = Array.from({ length: 20 }, (_, n) => [
      { kind: 'tool_call' as const, toolName: 'Bash', toolUseId: `t${n}`, command: 'pnpm vitest run', text: '{}' },
      { kind: 'tool_result' as const, toolUseId: `t${n}`, text: PASSED_RUN },
    ]).flat();
    const s = session('many', [{ kind: 'user', text: 'go' }, ...manyRuns], {
      commits: Array.from({ length: 10 }, (_, n) => String(n).padStart(40, '0')),
      filesTouched: Array.from({ length: 10 }, (_, n) => `file${n}.ts`),
    });

    const outline = outlineSession(s);

    expect(outline.commits).toHaveLength(6);
    expect(outline.files).toHaveLength(8);
    expect(outline.runs).toHaveLength(12);
  });

  it('gives a session with no user entry an empty first prompt, not a throw', () => {
    const s = session('silent', [{ kind: 'assistant', text: 'hello?' }]);
    expect(outlineSession(s).firstPrompt).toBe('');
  });
});

describe('outlinesWithin', () => {
  it('keeps every session and fits the limit for 12 long sessions', () => {
    const sessions = Array.from({ length: 12 }, (_, n) =>
      session(`s${n}`, [
        { kind: 'user', text: `Session ${n} prompt. ${'detail '.repeat(100)}` },
        { kind: 'assistant', text: `Session ${n} wrap-up. ${'notes '.repeat(100)}` },
      ]),
    );

    const outlines = outlinesWithin(sessions, 9000);

    expect(outlines).toHaveLength(12);
    expect(outlines.map((o) => o.id)).toEqual(sessions.map((s) => s.id));
    expect(JSON.stringify(outlines).length).toBeLessThanOrEqual(9000);
  });

  it('does not trim text that already fits', () => {
    const sessions = [session('s1', [{ kind: 'user', text: 'short' }, { kind: 'assistant', text: 'ok' }])];

    const outlines = outlinesWithin(sessions, 9000);

    expect(outlines[0]!.firstPrompt).toBe('short');
    expect(outlines[0]!.lastMessage).toBe('ok');
  });
});

describe('fallbackBeats', () => {
  it('orders newest sessions with commits first, and ranges each beat over the whole session', () => {
    const noCommitsOld = session('old-no-commits', [{ kind: 'user', text: 'a' }, { kind: 'assistant', text: 'b' }], {
      startedAt: '2026-01-01T00:00:00Z',
      commits: [],
    });
    const commitsOld = session('old-commits', [{ kind: 'user', text: 'c' }, { kind: 'assistant', text: 'd' }], {
      startedAt: '2026-01-02T00:00:00Z',
      commits: [SHA_A],
    });
    const commitsNew = session('new-commits', [{ kind: 'user', text: 'e' }, { kind: 'assistant', text: 'f' }, { kind: 'assistant', text: 'g' }], {
      startedAt: '2026-01-03T00:00:00Z',
      commits: [SHA_B],
    });
    const noCommitsNew = session('new-no-commits', [{ kind: 'user', text: 'h' }, { kind: 'assistant', text: 'i' }], {
      startedAt: '2026-01-04T00:00:00Z',
      commits: [],
    });

    const beats = fallbackBeats([noCommitsOld, commitsOld, commitsNew, noCommitsNew], 6);

    expect(beats.map((b) => b.sessionIds[0])).toEqual(['new-commits', 'old-commits', 'new-no-commits', 'old-no-commits']);
    expect(beats.every((b) => b.kind === 'feature')).toBe(true);
    const newCommitsBeat = beats.find((b) => b.sessionIds[0] === 'new-commits')!;
    expect(newCommitsBeat.entryRanges).toEqual([{ sessionId: 'new-commits', from: 0, to: 2 }]);
    expect(newCommitsBeat.commits).toEqual([SHA_B]);
  });

  it('keeps at most max beats, each with a unique sequential id', () => {
    const sessions = Array.from({ length: 8 }, (_, n) => session(`s${n}`, [{ kind: 'user', text: 'x' }]));

    const beats = fallbackBeats(sessions, 6);

    expect(beats).toHaveLength(6);
    expect(beats.map((b) => b.id)).toEqual(['beat_1', 'beat_2', 'beat_3', 'beat_4', 'beat_5', 'beat_6']);
  });
});

import type { CostMeter } from '@dailies/agent';

export class StageBudgetError extends Error {}

/**
 * Tracks what a stage has spent on `meter` since this call, against its own slice of the run
 * budget. `check()` throws once that spend passes `shareUsd`; what an earlier stage already spent
 * does not count against this share.
 */
export function stageMeter(meter: CostMeter, shareUsd: number): { check(): void; spent(): number } {
  const before = meter.total();
  const spent = () => meter.total() - before;
  return {
    spent,
    check(): void {
      const amount = spent();
      if (amount > shareUsd) throw new StageBudgetError(`stage spent $${amount.toFixed(4)} past its $${shareUsd.toFixed(4)} budget share`);
    },
  };
}

import { collectRuns } from '@dailies/verify';
import type { Beat, Session } from '@dailies/core';

const PROMPT_CHARS = 240;
const MESSAGE_CHARS = 240;
const MAX_COMMITS = 6;
const MAX_FILES = 8;
const MAX_RUNS = 12;
const BEAT_TITLE_CHARS = 80;
const BEAT_SUMMARY_CHARS = 400;

/** `text` in at most `max` characters; a cut is marked with an ellipsis that counts towards the limit. */
export function cut(text: string, max: number): string {
  if (max <= 0) return '';
  return text.length <= max ? text : `${text.slice(0, max - 1)}…`;
}

/** `text` as one line of at most `max` characters: line breaks and control characters become single spaces. */
export function oneLine(text: string, max: number): string {
  // eslint-disable-next-line no-control-regex
  return cut(text.replace(/[\u0000-\u001f\u007f\u0085  \s]+/g, ' ').trim(), max);
}

export interface SessionOutline {
  id: string;
  agent: string;
  model: string | null;
  startedAt: string;
  minutes: number;
  turns: number;
  entries: number;
  firstPrompt: string; // first user entry, at most 240 characters
  lastMessage: string; // last assistant entry, at most 240 characters
  commits: string[]; // short SHAs, at most 6
  files: string[]; // at most 8
  runs: string[]; // e.g. "test fail @120", "test pass @188", at most 12, in order
  edits: number; // file-editing tool calls
}

function minutesBetween(startedAt: string, endedAt: string | null): number {
  if (!endedAt) return 0;
  const ms = Date.parse(endedAt) - Date.parse(startedAt);
  return ms > 0 ? Math.round(ms / 60000) : 0;
}

/** One line per recorded command: its kind, outcome and entry index, in session order. */
function runLines(session: Session, max: number): string[] {
  return collectRuns(session)
    .slice(0, max)
    .map((r) => `${r.cls} ${r.outcome} @${r.index}`);
}

/** A compact summary of one session: enough for the editor to choose beats without reading the transcript. */
export function outlineSession(session: Session): SessionOutline {
  const firstPrompt = session.entries.find((e) => e.kind === 'user')?.text ?? '';
  const lastAssistant = [...session.entries].reverse().find((e) => e.kind === 'assistant' && e.text.trim() !== '');
  const edits = session.entries.filter((e) => e.kind === 'tool_call' && e.filePath !== undefined).length;
  return {
    id: session.id,
    agent: session.agent,
    model: session.model,
    startedAt: session.startedAt,
    minutes: minutesBetween(session.startedAt, session.endedAt),
    turns: session.turnCount,
    entries: session.entries.length,
    firstPrompt: oneLine(firstPrompt, PROMPT_CHARS),
    lastMessage: oneLine(lastAssistant?.text ?? '', MESSAGE_CHARS),
    commits: session.commits.slice(0, MAX_COMMITS),
    files: session.filesTouched.slice(0, MAX_FILES),
    runs: runLines(session, MAX_RUNS),
    edits,
  };
}

function trimmedTo(outline: SessionOutline, cap: number): SessionOutline {
  return { ...outline, firstPrompt: cut(outline.firstPrompt, cap), lastMessage: cut(outline.lastMessage, cap) };
}

/**
 * Every session's outline, `firstPrompt` and `lastMessage` trimmed evenly, as far as needed, so the
 * JSON fits `maxChars`. No session is ever dropped.
 */
export function outlinesWithin(sessions: Session[], maxChars: number): SessionOutline[] {
  const full = sessions.map(outlineSession);
  const fits = (cap: number) => JSON.stringify(full.map((o) => trimmedTo(o, cap))).length <= maxChars;
  if (fits(PROMPT_CHARS)) return full;

  let lo = 0;
  let hi = PROMPT_CHARS;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (fits(mid)) lo = mid;
    else hi = mid - 1;
  }
  return full.map((o) => trimmedTo(o, lo));
}

/** The newest sessions with commits first, as whole-session beats, for when the editor could not produce any. */
export function fallbackBeats(sessions: Session[], max: number): Beat[] {
  const sorted = [...sessions].sort((a, b) => {
    const byCommit = (a.commits.length > 0 ? 0 : 1) - (b.commits.length > 0 ? 0 : 1);
    return byCommit !== 0 ? byCommit : b.startedAt.localeCompare(a.startedAt);
  });
  return sorted.slice(0, max).map((s, n) => {
    const prompt = s.entries.find((e) => e.kind === 'user')?.text ?? s.id;
    return {
      id: `beat_${n + 1}`,
      kind: 'feature' as const,
      title: oneLine(prompt, BEAT_TITLE_CHARS),
      summary: oneLine(`Session ${s.id}: ${prompt}`, BEAT_SUMMARY_CHARS),
      sessionIds: [s.id],
      entryRanges: [{ sessionId: s.id, from: 0, to: Math.max(0, s.entries.length - 1) }],
      commits: s.commits,
    };
  });
}

